using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;public class ParticipantController:Controller{readonly RaceDayApiClient api;public ParticipantController(RaceDayApiClient a)=>api=a;bool Role()=>HttpContext.Session.GetString("Role")=="Participant";IActionResult Gate()=>HttpContext.Session.GetInt32("UserId")==null?RedirectToAction("Login","Account"):Forbid();
public async Task<IActionResult>MyEvents(){if(!Role())return Gate();return View(await api.Get<List<Enrolment>>("api/enrolments/mine")??new());}
public async Task<IActionResult>MyResults(){if(!Role())return Gate();return View(await api.Get<List<Result>>("api/results/mine")??new());}
public async Task<IActionResult>Profile(){if(!Role())return Gate();var u=await api.Get<User>("api/profile");return View(new ProfileVm{FirstName=u?.FirstName??"",LastName=u?.LastName??"",Phone=u?.Phone,ProfileImageUrl=u?.ProfileImageUrl});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Profile(ProfileVm vm){if(!Role())return Gate();if(!ModelState.IsValid)return View(vm);var r=await api.Send<User>(HttpMethod.Put,"api/profile",vm);if(!r.Ok){ModelState.AddModelError("",r.Message);return View(vm);}TempData["Success"]="Profile updated.";return RedirectToAction(nameof(Profile));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>UploadProfileImage(IFormFile file){if(!Role())return Gate();if(file==null||file.Length==0){TempData["Error"]="Choose an image first.";return RedirectToAction(nameof(Profile));}var r=await api.Upload("api/profile/image",file);TempData[r.Ok?"Success":"Error"]=r.Ok?"Profile picture uploaded.":r.Message;return RedirectToAction(nameof(Profile));}}